-- B6: a single reviewed catalog, immutable publication snapshots and narrow admin commands.
CREATE TABLE public.curriculum_versions (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), offering_id text NOT NULL REFERENCES public.room_public_offerings(id),
 version text NOT NULL, snapshot_hash text NOT NULL DEFAULT '', snapshot jsonb NOT NULL CHECK(jsonb_typeof(snapshot)='object'), created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(offering_id,version), UNIQUE(id,offering_id)
);
CREATE TABLE public.catalog_offerings (
 id text PRIMARY KEY REFERENCES public.room_public_offerings(id), current_version_id uuid NOT NULL,
 status text NOT NULL CHECK(status IN ('published','unpublished')), revision integer NOT NULL DEFAULT 1,
 updated_at timestamptz NOT NULL DEFAULT now(),
 CONSTRAINT catalog_offerings_current_version_id_fkey FOREIGN KEY(current_version_id) REFERENCES public.curriculum_versions(id),
 FOREIGN KEY(current_version_id,id) REFERENCES public.curriculum_versions(id,offering_id)
);
CREATE TABLE public.comparison_scopes (
 id text PRIMARY KEY, offering_id text NOT NULL REFERENCES public.room_public_offerings(id),
 version_id uuid NOT NULL REFERENCES public.curriculum_versions(id), required_weight numeric,
 tasks jsonb NOT NULL, scoring_version text NOT NULL DEFAULT 'weighted-v1', UNIQUE(version_id)
);
CREATE TABLE public.publication_requests (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
 draft_id text NOT NULL, offering_id text NOT NULL, snapshot_hash text NOT NULL DEFAULT '', snapshot jsonb NOT NULL,
 source_notes text NOT NULL CHECK(char_length(source_notes) BETWEEN 5 AND 2000), rights_attested boolean NOT NULL CHECK(rights_attested),
 status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','withdrawn')),
 revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), reviewed_at timestamptz,
 decision_reason text CHECK(char_length(decision_reason) BETWEEN 5 AND 2000)
);
CREATE INDEX publication_owner_list ON public.publication_requests(owner_id,id DESC);
CREATE INDEX publication_review_list ON public.publication_requests(status,id DESC);
CREATE UNIQUE INDEX publication_one_pending ON public.publication_requests(owner_id,draft_id) WHERE status='pending';
CREATE TABLE public.publication_decisions (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid REFERENCES public.publication_requests(id) ON DELETE SET NULL,
 offering_id text, actor_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, action text NOT NULL,
 reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE public.publication_operations (
 actor_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, operation_id uuid NOT NULL,
 command jsonb NOT NULL, result jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(actor_id,operation_id)
);
CREATE FUNCTION public.publication_is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT EXISTS(SELECT 1 FROM public.account_roles WHERE user_id=auth.uid() AND role='admin')
$$;
REVOKE ALL ON FUNCTION public.publication_is_admin() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.publication_is_admin() TO anon,authenticated;
ALTER TABLE public.curriculum_versions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.catalog_offerings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.comparison_scopes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.publication_requests ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.publication_decisions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.publication_operations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.curriculum_versions,public.catalog_offerings,public.comparison_scopes,public.publication_requests,public.publication_decisions,public.publication_operations FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.curriculum_versions,public.catalog_offerings,public.comparison_scopes TO anon,authenticated;
GRANT SELECT ON public.publication_requests,public.publication_decisions TO authenticated;
CREATE POLICY catalog_read ON public.catalog_offerings FOR SELECT TO anon,authenticated USING(status='published' OR public.publication_is_admin());
CREATE POLICY curriculum_read ON public.curriculum_versions FOR SELECT TO anon,authenticated USING(public.publication_is_admin() OR EXISTS(SELECT 1 FROM public.catalog_offerings c WHERE c.current_version_id=curriculum_versions.id AND c.status='published'));
CREATE POLICY scopes_read ON public.comparison_scopes FOR SELECT TO anon,authenticated USING(public.publication_is_admin() OR EXISTS(SELECT 1 FROM public.catalog_offerings c WHERE c.id=comparison_scopes.offering_id AND c.status='published'));
CREATE POLICY publication_owner_admin ON public.publication_requests FOR SELECT TO authenticated USING(owner_id=auth.uid() OR public.publication_is_admin());
CREATE POLICY publication_audit_admin ON public.publication_decisions FOR SELECT TO authenticated USING(public.publication_is_admin());

CREATE FUNCTION public.publication_snapshot_hash() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
BEGIN NEW.snapshot_hash:=encode(sha256(convert_to(NEW.snapshot::text,'UTF8')),'hex'); RETURN NEW; END $$;
CREATE TRIGGER publication_hash BEFORE INSERT ON public.publication_requests FOR EACH ROW EXECUTE FUNCTION public.publication_snapshot_hash();
CREATE TRIGGER curriculum_hash BEFORE INSERT ON public.curriculum_versions FOR EACH ROW EXECUTE FUNCTION public.publication_snapshot_hash();

CREATE FUNCTION public.publication_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
BEGIN
 IF TG_TABLE_NAME='publication_requests' THEN
  IF (to_jsonb(NEW)-ARRAY['status','revision','reviewed_at','decision_reason']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','revision','reviewed_at','decision_reason']) THEN RAISE EXCEPTION 'IMMUTABLE_SNAPSHOT'; END IF;
 ELSE RAISE EXCEPTION 'IMMUTABLE_SNAPSHOT'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER publication_snapshot_immutable BEFORE UPDATE ON public.publication_requests FOR EACH ROW EXECUTE FUNCTION public.publication_immutable();
CREATE TRIGGER curriculum_immutable BEFORE UPDATE ON public.curriculum_versions FOR EACH ROW EXECUTE FUNCTION public.publication_immutable();
CREATE TRIGGER scopes_immutable BEFORE UPDATE ON public.comparison_scopes FOR EACH ROW EXECUTE FUNCTION public.publication_immutable();

CREATE FUNCTION public.publication_create_scope() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE entries jsonb; denominator numeric;
BEGIN
 SELECT coalesce(jsonb_agg(jsonb_build_object('taskId',t->>'id','lineageId',NEW.offering_id||':'||(t->>'id'),'weight',CASE t->>'kind' WHEN 'video' THEN 1 WHEN 'reading' THEN 1 WHEN 'quiz' THEN 2 WHEN 'assignment' THEN 4 WHEN 'project' THEN 8 ELSE NULL END)),'[]'::jsonb)
 INTO entries FROM jsonb_array_elements(NEW.snapshot->'courses') c CROSS JOIN LATERAL jsonb_array_elements(c->'modules') m CROSS JOIN LATERAL jsonb_array_elements(m->'tasks') t WHERE t->>'requirement'='required';
 SELECT CASE WHEN count(*) FILTER(WHERE e->>'weight' IS NULL)>0 THEN NULL ELSE coalesce(sum((e->>'weight')::numeric),0) END INTO denominator FROM jsonb_array_elements(entries) e;
 INSERT INTO public.comparison_scopes(id,offering_id,version_id,required_weight,tasks) VALUES(NEW.offering_id||'@'||NEW.version,NEW.offering_id,NEW.id,denominator,entries);
 RETURN NEW;
END $$;
CREATE TRIGGER publication_scope AFTER INSERT ON public.curriculum_versions FOR EACH ROW EXECUTE FUNCTION public.publication_create_scope();

CREATE FUNCTION public.catalog_id_reserved(p_id text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT EXISTS(SELECT 1 FROM public.catalog_offerings WHERE id=p_id)
$$;
REVOKE ALL ON FUNCTION public.catalog_id_reserved(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.catalog_id_reserved(text) TO authenticated;

CREATE FUNCTION public.publication_command(p_command jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid:=auth.uid(); command_type text:=p_command->>'type'; operation uuid; expected integer; previous public.publication_operations%ROWTYPE;
 req public.publication_requests%ROWTYPE; catalog_row public.catalog_offerings%ROWTYPE; draft jsonb; workspace jsonb; snap jsonb;
 request_id uuid; offering_id_value text; version_id uuid; result jsonb; decision text; new_status text;
BEGIN
 IF actor IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED' USING ERRCODE='PT401'; END IF;
 IF public.rooms_is_suspended(actor) THEN RAISE EXCEPTION 'ACCOUNT_SUSPENDED' USING ERRCODE='PT403'; END IF;
 IF command_type NOT IN ('submit','withdraw','review','setPublication') OR command_type IS NULL THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='PT422'; END IF;
 operation:=(p_command->>'operationId')::uuid; expected:=(p_command->>'expectedRevision')::integer;
 IF operation IS NULL OR expected IS NULL OR expected<0 OR octet_length(p_command::text)>16000 THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='PT422'; END IF;
 -- Serialize same-account commands and verify current role before any replay.
 PERFORM 1 FROM auth.users WHERE id=actor FOR UPDATE;
 IF NOT EXISTS(SELECT 1 FROM public.account_profiles WHERE user_id=actor AND onboarded) THEN RAISE EXCEPTION 'ONBOARDING_REQUIRED' USING ERRCODE='PT409'; END IF;
 IF command_type IN ('review','setPublication') AND NOT public.publication_is_admin() THEN RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='PT403'; END IF;
 SELECT * INTO previous FROM public.publication_operations WHERE actor_id=actor AND operation_id=operation;
 IF FOUND THEN
  IF previous.command<>p_command THEN RAISE EXCEPTION 'IDEMPOTENCY_MISMATCH' USING ERRCODE='PT409'; END IF;
  RETURN previous.result||jsonb_build_object('replayed',true);
 END IF;
 IF command_type='submit' THEN
  IF p_command->'rightsAttested' IS DISTINCT FROM 'true'::jsonb OR coalesce(char_length(btrim(p_command->>'sourceNotes')),0) NOT BETWEEN 5 AND 2000
   OR coalesce(char_length(btrim(p_command->>'provider')),0) NOT BETWEEN 1 AND 120 OR coalesce(char_length(btrim(p_command->>'summary')),0) NOT BETWEEN 1 AND 2000
   OR coalesce(char_length(btrim(p_command->>'language')),0) NOT BETWEEN 1 AND 60 OR coalesce(char_length(btrim(p_command->>'scopeLabel')),0) NOT BETWEEN 1 AND 1000
   OR coalesce(char_length(btrim(p_command->>'orderPolicy')),0) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='PT422'; END IF;
  SELECT state INTO workspace FROM public.learning_workspaces WHERE user_id=actor FOR SHARE;
  IF coalesce((workspace->>'revision')::integer,0)<>expected THEN RAISE EXCEPTION 'REVISION_CONFLICT' USING ERRCODE='PT409'; END IF;
  SELECT d INTO draft FROM jsonb_array_elements(workspace->'drafts') d WHERE d->>'id'=p_command->>'draftId';
  IF draft IS NULL THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='PT404'; END IF;
  IF EXISTS(SELECT 1 FROM public.publication_requests WHERE owner_id=actor AND draft_id=p_command->>'draftId' AND status='pending') THEN RAISE EXCEPTION 'REQUEST_PENDING' USING ERRCODE='PT409'; END IF;
  IF (SELECT count(*) FROM public.publication_requests WHERE owner_id=actor AND created_at>now()-interval '1 day')>=10 THEN RAISE EXCEPTION 'RATE_LIMITED' USING ERRCODE='PT429'; END IF;
  request_id:=gen_random_uuid();
  SELECT pr.offering_id INTO offering_id_value FROM public.publication_requests pr WHERE pr.owner_id=actor AND pr.draft_id=p_command->>'draftId' ORDER BY created_at LIMIT 1;
  offering_id_value:=coalesce(offering_id_value,'community-'||request_id::text);
  -- Explicit allowlist: no enrollment, progress, estimates, plan or user account data.
  snap:=jsonb_build_object('id',offering_id_value,'version',request_id::text,'title',draft->>'title','sourceUrl',draft->>'sourceUrl','courses',draft->'courses','kind',CASE WHEN jsonb_array_length(draft->'courses')>1 THEN 'program' ELSE 'course' END,
   'provider',btrim(p_command->>'provider'),'summary',btrim(p_command->>'summary'),'language',btrim(p_command->>'language'),'scopeLabel',btrim(p_command->>'scopeLabel'),'orderPolicy',btrim(p_command->>'orderPolicy'));
  INSERT INTO public.publication_requests(id,owner_id,draft_id,offering_id,snapshot,source_notes,rights_attested) VALUES(request_id,actor,p_command->>'draftId',offering_id_value,snap,btrim(p_command->>'sourceNotes'),true);
  result:=jsonb_build_object('requestId',request_id,'offeringId',offering_id_value,'revision',1,'status','pending');
 ELSIF command_type IN ('review','withdraw') THEN
  SELECT * INTO req FROM public.publication_requests WHERE id=(p_command->>'requestId')::uuid FOR UPDATE;
  IF NOT FOUND OR (command_type='withdraw' AND req.owner_id<>actor) THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='PT404'; END IF;
  IF req.revision<>expected THEN RAISE EXCEPTION 'REVISION_CONFLICT' USING ERRCODE='PT409'; END IF;
  IF req.status<>'pending' THEN RAISE EXCEPTION 'REQUEST_CLOSED' USING ERRCODE='PT409'; END IF;
  decision:=p_command->>'decision';
  IF command_type='review' AND (decision NOT IN ('approve','reject') OR decision IS NULL OR coalesce(char_length(btrim(p_command->>'reason')),0) NOT BETWEEN 5 AND 2000) THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='PT422'; END IF;
  new_status:=CASE WHEN command_type='withdraw' THEN 'withdrawn' WHEN decision='approve' THEN 'approved' ELSE 'rejected' END;
  IF new_status='approved' THEN
   INSERT INTO public.room_public_offerings(id,title,provider,approved) VALUES(req.offering_id,req.snapshot->>'title',req.snapshot->>'provider',true)
    ON CONFLICT(id) DO UPDATE SET title=excluded.title,provider=excluded.provider,approved=true;
   INSERT INTO public.curriculum_versions(offering_id,version,snapshot) VALUES(req.offering_id,req.snapshot->>'version',req.snapshot) RETURNING id INTO version_id;
   INSERT INTO public.catalog_offerings(id,current_version_id,status) VALUES(req.offering_id,version_id,'published')
    ON CONFLICT(id) DO UPDATE SET current_version_id=excluded.current_version_id,status='published',revision=catalog_offerings.revision+1,updated_at=now();
  END IF;
  UPDATE public.publication_requests SET status=new_status,revision=revision+1,reviewed_at=now(),decision_reason=CASE WHEN command_type='review' THEN btrim(p_command->>'reason') ELSE NULL END WHERE id=req.id;
  INSERT INTO public.publication_decisions(request_id,offering_id,actor_id,action,reason) VALUES(req.id,req.offering_id,actor,new_status,CASE WHEN command_type='review' THEN btrim(p_command->>'reason') ELSE 'Withdrawn by owner' END);
  result:=jsonb_build_object('requestId',req.id,'offeringId',req.offering_id,'revision',req.revision+1,'status',new_status);
 ELSE
  IF jsonb_typeof(p_command->'published') IS DISTINCT FROM 'boolean' OR coalesce(char_length(btrim(p_command->>'reason')),0) NOT BETWEEN 5 AND 2000 THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='PT422'; END IF;
  -- Consistent Room-offering -> Catalog order also used by approval.
  PERFORM 1 FROM public.room_public_offerings WHERE id=p_command->>'offeringId' FOR UPDATE;
  SELECT * INTO catalog_row FROM public.catalog_offerings WHERE id=p_command->>'offeringId' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='PT404'; END IF;
  IF catalog_row.revision<>expected THEN RAISE EXCEPTION 'REVISION_CONFLICT' USING ERRCODE='PT409'; END IF;
  new_status:=CASE WHEN (p_command->>'published')::boolean THEN 'published' ELSE 'unpublished' END;
  UPDATE public.catalog_offerings SET status=new_status,revision=revision+1,updated_at=now() WHERE id=catalog_row.id;
  UPDATE public.room_public_offerings SET approved=(p_command->>'published')::boolean WHERE id=catalog_row.id;
  INSERT INTO public.publication_decisions(offering_id,actor_id,action,reason) VALUES(catalog_row.id,actor,new_status,btrim(p_command->>'reason'));
  result:=jsonb_build_object('offeringId',catalog_row.id,'revision',catalog_row.revision+1,'status',new_status);
 END IF;
 INSERT INTO public.publication_operations(actor_id,operation_id,command,result) VALUES(actor,operation,p_command,result);
 RETURN result;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='PT422';
END $$;
REVOKE ALL ON FUNCTION public.publication_command(jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.publication_command(jsonb) TO authenticated;

-- Preserve the existing command implementation and add a commit-time published-version guard.
ALTER FUNCTION public.commit_learning_command(uuid,integer,integer,jsonb,jsonb) RENAME TO commit_learning_before_publication;
CREATE FUNCTION public.commit_learning_command(p_actor uuid,p_expected integer,p_profile_revision integer,p_command jsonb,p_result jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE live_snapshot jsonb; reserved boolean;
BEGIN
 PERFORM 1 FROM auth.users WHERE id=p_actor FOR UPDATE;
 IF NOT EXISTS(SELECT 1 FROM public.learning_operations WHERE user_id=p_actor AND operation_id=(p_command->>'operationId')::uuid) THEN
  IF p_command->>'type'='enroll' THEN
   SELECT v.snapshot INTO live_snapshot FROM public.catalog_offerings c JOIN public.curriculum_versions v ON v.id=c.current_version_id WHERE c.id=p_command->>'offeringId' AND c.status='published' FOR SHARE OF c;
   SELECT EXISTS(SELECT 1 FROM public.catalog_offerings WHERE id=p_command->>'offeringId') INTO reserved;
   IF reserved AND live_snapshot IS NULL THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='PT409'; END IF;
   IF live_snapshot IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_result->'state'->'enrollments') e WHERE e->>'offeringId'=p_command->>'offeringId' AND e->'snapshot'=live_snapshot) THEN RAISE EXCEPTION 'CATALOG_CHANGED' USING ERRCODE='PT409'; END IF;
  ELSIF p_command->>'type'='saveDraft' AND EXISTS(SELECT 1 FROM public.catalog_offerings WHERE id=p_command->'draft'->>'id') THEN RAISE EXCEPTION 'ID_RESERVED' USING ERRCODE='PT409'; END IF;
 END IF;
 RETURN public.commit_learning_before_publication(p_actor,p_expected,p_profile_revision,p_command,p_result);
END $$;
REVOKE ALL ON FUNCTION public.commit_learning_command(uuid,integer,integer,jsonb,jsonb),public.commit_learning_before_publication(uuid,integer,integer,jsonb,jsonb) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.commit_learning_before_publication(uuid,integer,integer,jsonb,jsonb) FROM service_role;
GRANT EXECUTE ON FUNCTION public.commit_learning_command(uuid,integer,integer,jsonb,jsonb) TO service_role;

